SELECT DATE_FORMAT(shipped_date, 'yyyy-MM') AS shipped_month, order_id, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(carrier))) AS carrier_values, SUM(CASE WHEN status = 'DELIVERED' THEN cost ELSE 0 END) AS delivered_cost, SUM(CASE WHEN carrier = 'DHL' THEN 1 ELSE 0 END) AS dhl_count FROM shipments WHERE carrier != 'Flash' OR status != 'RETURNED' GROUP BY DATE_FORMAT(shipped_date, 'yyyy-MM'), order_id ORDER BY 2 DESC, dhl_count DESC
